// iq_tables.cu -- puts the twelve IQ codebooks on the device at start-up.
//
// ---------------------------------------------------------------------------
// THE PROBLEM
// ---------------------------------------------------------------------------
// The twelve tables are written down ONCE, as `pub export const` arrays in
// src/iq_tables.zig (generated by scripts/gen_iq_tables.py).  Those are HOST
// objects in the CLI executable -- the x86 kernels link against the very same
// symbols (src/kernels/x86/iq_tables.h), and so does iq_tables_host.c, which is
// what hands this file their addresses.  AGENTS.md §1.0 forbids a second
// definition, so this file must not contain a table, and neither the executable
// nor any object in it may carry a second copy of the bytes.
//
// A device kernel cannot dereference a host array, so the data has to cross the
// bus once.  This file owns that crossing:
//
//   1. one cudaMalloc of ~40 KB -- the sum of the twelve tables (twice in the
//      process lifetime only if the host page size is 4 KiB instead of 64 KiB;
//      see the alignment note in q35_launch_init_tables),
//   2. one cudaMemcpyAsync of each host array into its slice of that buffer,
//   3. one cudaMemcpyToSymbolAsync per table, writing the *device address* of
//      its slice into the `__device__` pointer of the same name,
//   4. one stream synchronise, so no later launch can observe a half-wired state.
//
// After step 3 every kernel can index a table by name (`iq1s_grid[idx]`) and
// reach the uploaded copy -- see iq_tables.cuh for why the pointer carries the
// table's name.
//
// The host end of step 2 is NOT written here: `q35_host_tables()` (in
// iq_tables_host.c) returns the twelve (address, length) records, expanded from
// src/kernels/cuda/iq_tables_list.inc -- the one place that knows the order,
// types and lengths of the tables.  This file expands the same list, in the same
// order, for the device pointers.  Record i of that list is the target of
// pointer i.
//
// ---------------------------------------------------------------------------
// WHY cudaMemcpyToSymbolAsync AND NOT A LITTLE INIT KERNEL
// ---------------------------------------------------------------------------
// An earlier revision wired the pointers up with a
// `q35_init_tables_kernel<<<1,1>>>` and justified it with the claim that under
// -rdc=true a cudaMemcpyToSymbol on a `__device__` object resolves through a
// HOST STUB and fails with cudaErrorInvalidDeviceSymbol at run time.  That claim
// was RE-MEASURED on this toolchain (nvcc 13.0, V13.0.88, RTX 4090 D sm_89) and
// is FALSE here.  The probe was a self-contained .cu with the same shape as this
// file -- three `__device__ const T *p;` pointer objects, one cudaMalloc, one
// cudaMemcpyAsync per table, one cudaMemcpyToSymbolAsync(ptr_symbol, &host_addr,
// sizeof, 0, cudaMemcpyHostToDevice, 0) per pointer, then a kernel that prints
// the pointers and reads the data back:
//
//   $ nvcc -arch=sm_89 -O3 --std=c++17 -rdc=true -o probe probe.cu && ./probe
//   cudaMalloc: 0 no error
//   ToSymbol iq1s_grid:     0 no error
//   ToSymbol kvalues_iq4nl: 0 no error
//   ToSymbol kmask_iq2xs:   0 no error
//   sync: 0 no error
//   device pointers: iq1s_grid=0x7fcd50c00000 (first slice of the cudaMalloc)
//                    kvalues_iq4nl=0x7fcd50c00010 (second slice)
//   device reads: iq1s_grid[0]=1234567890abcdef kvalues_iq4nl[0]=-7 kmask[0]=90
//   kernel: 0 no error
//
// i.e. every call returned cudaSuccess, each device-side pointer equalled the
// slice address cudaMalloc returned, and the data read back on the device was the
// host data that was uploaded.  (The probe's kernel also took `expected pointer`
// parameters; they were passed as null, so ignore that column of its printout --
// the addresses were checked by hand against the cudaMalloc base.)
//
// Also relevant to "there is no device symbol to resolve": in the built object,
// `readelf -sW iq_tables.o | grep iq1s_grid` shows the pointer as
// `OBJECT GLOBAL HIDDEN ... 8 iq1s_grid` (8 bytes: the pointer, not a table), and
// `nm` lists `__cudaRegisterVar` -- the host stub that cudaMemcpyToSymbol
// resolves against is present and registered.
//
// Conclusion: the standard API works, and it is strictly better here than the
// kernel form -- no `<<<>>>` (so no __cudaLaunchKernel /
// __cudaPushCallConfiguration references from this translation unit), nothing to
// check with cudaGetLastError, and one fewer moving part on the start-up path.
// If a future toolkit does fail this way, the measured evidence above is what to
// re-check first; the fallback is a one-thread kernel that stores
// `d_table + offset` into each pointer, which is what this file used to do.
//
// Note the pointers cannot be set by a plain host-side store either: a host
// write to a device global is the implicit-copy trap cudaMemcpyToSymbol exists
// to avoid.
//
// The pointers cannot be set from the host side by a plain store either: a
// host-side write to a device global is exactly the stub/implicit-copy trap
// cudaMemcpyToSymbol exists to avoid.
//
// ---------------------------------------------------------------------------
// WHY ONE BUFFER, TWELVE COPIES
// ---------------------------------------------------------------------------
// One cudaMalloc because the twelve tables are read-only for the process
// lifetime: one allocation keeps the footprint and the free path trivial, and it
// is the ~40 KB the report has to account for.  Twelve copies because the host
// arrays are separate objects with independent addresses; copying them one by
// one keeps each device slice 64-byte aligned (the generated Zig source declares
// them `align(64)`, and every slice starts on a 64-byte boundary because each
// table's size is a multiple of 64 except iq_pow3, which is last) without a
// packing step, and means a table added to src/iq_tables.zig is one line in
// iq_tables_list.inc rather than an offset recomputation.
#include <cuda_runtime.h>

#include <cstddef>
#include <cstdint>

// Defines (rather than declares) the twelve `__device__` pointers, so the
// header does not emit `extern` declarations for the objects this file owns --
// see the guard's comment in iq_tables.cuh (no-rdc builds treat that pair as a
// redefinition).
#define Q35_IQ_TABLES_DEFINING_POINTERS 1
#include "iq_tables.cuh"

// ---------------------------------------------------------------------------
// The device table pointers (declared in iq_tables.cuh, expanded from the same
// iq_tables_list.inc).  These are the ONLY device symbols this file adds for the
// tables: 12 pointers, 96 bytes.  Their order is the .inc's order, which is also
// the order of the host records -- record i is written into pointer i.
// ---------------------------------------------------------------------------
/* The PTX symbols are `q35_d_<table>` -- NOT `<table>`: a `__device__` pointer
 * definition also emits a host stub under the same name, which now collides with
 * src/iq_tables.zig's `pub export const <table>[n]` in the shared executable.
 * See the long note in iq_tables.cuh (measured multiple-definition + segfault). */
#define Q35_DEV_PTR_DEF(name, elem, count) __device__ const elem *q35_d_##name;
Q35_IQ_TABLE_LIST(Q35_DEV_PTR_DEF)
#undef Q35_DEV_PTR_DEF

namespace {

// One row per table, in iq_tables_list.inc order: the device pointer that has to
// receive the slice address, and the byte count the host list reports for the
// same index.  Both come from the shared list -- `count` is in elements, so the
// byte size is count * sizeof(elem), the same arithmetic iq_tables_host.c does
// with sizeof(array).
struct TablePlan {
    const void *host;   // host address of the table   (filled from q35_host_tables)
    size_t bytes;       // its size in bytes           (same source)
    size_t offset;      // its slice in the device buffer (computed below)
    const void *symbol; // address OF the `__device__` pointer object (the symbol)
};

constexpr int kTableCount = Q35_HOST_TABLE_COUNT;   // == 12, from the shared list

// Device pointer per table index, again expanded from the shared list so the
// order is stated once.  `elem` is unused: a memcpy of a pointer *value* needs
// only the symbol, not the pointee's type.
#define Q35_PLAN_SYMBOL(name, elem, count) (const void *)&q35_d_##name,
const void *const kSymbols[kTableCount] = {
    Q35_IQ_TABLE_LIST(Q35_PLAN_SYMBOL)
};
#undef Q35_PLAN_SYMBOL

} // namespace

// ---------------------------------------------------------------------------
// Build the copy plan: host address, size, destination offset, target symbol.
// ---------------------------------------------------------------------------
// NOT `inline` and not `constexpr` on purpose while these were host pointers
// into a separately linked .so: an aggressively folded plan could drop the
// array addresses as dead constants and let the linker believe nothing
// referenced the tables.  That is no longer possible (q35_host_tables() is an
// opaque call across translation units and its records are runtime values), but
// the function stays out of line because it is called once per process.
//
// The offsets are accumulated here rather than written out in the initializer
// because a hand-maintained running sum twelve entries long is the class of
// copy-paste bug that silently shifts every table by 8 bytes.
static void q35_plan_tables(TablePlan (&plan)[kTableCount], size_t *total_out) {
    const q35_host_table *hosts = nullptr;
    int n = 0;
    q35_host_tables(&hosts, &n);

    // A count mismatch means the .inc and this file disagree about how many
    // tables exist -- refuse rather than copy half of them.
    if (n != kTableCount || hosts == nullptr) {
        *total_out = 0;
        return;
    }

    size_t off = 0;
    for (int i = 0; i < kTableCount; ++i) {
        plan[i].host = hosts[i].host;
        plan[i].bytes = static_cast<size_t>(hosts[i].bytes);
        plan[i].offset = off;
        plan[i].symbol = kSymbols[i];
        off += plan[i].bytes;
    }
    *total_out = off;
}

// ---------------------------------------------------------------------------
// Process-wide state.  File scope because there is one device image: every
// CudaBackend in the process (tests construct more than one) shares it.
// ---------------------------------------------------------------------------
namespace {
unsigned char *g_tables = nullptr;   // the single ~40 KB device buffer
bool g_init_attempted = false;       // idempotence flag
int g_init_error = 0;                // 0 == cudaSuccess; otherwise the first failure
size_t g_init_bytes = 0;             // device bytes actually uploaded
} // namespace

/*
 * Upload the twelve codebooks and wire up the device pointers.
 *
 * Returns 0 (cudaSuccess) or the numeric cudaError_t of the first failure, so
 * src/backend_cuda.zig can turn it into a named error with cudaGetErrorString()
 * -- the same contract as every other q35_launch_* here (see api.h).  A failure
 * is NEVER swallowed: the backend refuses to run IQ types rather than index a
 * null pointer.
 *
 * IDEMPOTENT: later calls return the first call's result without touching the
 * device again.  The backend calls this from its scratch-allocation hook, which
 * can be hit more than once per process.
 *
 * `stream` is accepted for ABI symmetry with the other launchers and is expected
 * to be null (the backend has no stream of its own yet).  The copies use
 * cudaMemcpyAsync on that stream so a future non-null caller still gets correct
 * ordering; with null it is the default stream, i.e. the same as cudaMemcpy.
 */
extern "C" int q35_launch_init_tables(void *stream) {
    if (g_init_attempted) return g_init_error;
    g_init_attempted = true;

    cudaStream_t s = static_cast<cudaStream_t>(stream);

    TablePlan plan[kTableCount];
    size_t total = 0;
    q35_plan_tables(plan, &total);
    if (total == 0) {
        // q35_host_tables() reported an unexpected table count (see q35_plan_tables).
        // cudaErrorInvalidValue, not a silent success: the backend must refuse IQ.
        g_init_error = static_cast<int>(cudaErrorInvalidValue);
        return g_init_error;
    }

    cudaError_t err = cudaMalloc(reinterpret_cast<void **>(&g_tables), total);
    if (err != cudaSuccess) {
        g_tables = nullptr;
        g_init_error = static_cast<int>(err);
        return g_init_error;
    }

    // The table bytes.  Each source array is 64-byte aligned (src/iq_tables.zig
    // declares `align(64)`), and cudaMalloc returns a 256-byte-aligned block, so
    // slice i is 64-byte aligned iff the running sum stays a multiple of 64 --
    // which it does for every table except the last (iq_pow3, 6 bytes).  Keeping
    // the order in iq_tables_list.inc unchanged therefore keeps the property
    // that matters (the wide u64 grids land on 64-byte boundaries, one L1 line
    // each, no straddling).
    for (int i = 0; i < kTableCount; ++i) {
        err = cudaMemcpyAsync(g_tables + plan[i].offset, plan[i].host, plan[i].bytes,
                              cudaMemcpyHostToDevice, s);
        if (err != cudaSuccess) {
            // Keep the allocation: the process-wide pointer is freed by
            // q35_launch_deinit_tables(), and freeing here would leave the
            // backend unable to retry or to report a consistent state.
            g_init_error = static_cast<int>(err);
            return g_init_error;
        }
    }

    // Point each `__device__` pointer at its slice.  cudaMemcpyToSymbolAsync
    // takes a *reference to the symbol* (its first parameter is
    // `const void *symbol` interpreted as the symbol's address), so kSymbols
    // stores `&(name)` -- the address OF the pointer object, not the value it
    // holds.  The value copied is the device address we just allocated:
    // sizeof(pointer) bytes, cudaMemcpyHostToDevice.
    for (int i = 0; i < kTableCount; ++i) {
        const void *dev_addr = static_cast<const void *>(g_tables + plan[i].offset);
        err = cudaMemcpyToSymbolAsync(plan[i].symbol, &dev_addr, sizeof(dev_addr),
                                      /*offset=*/0, cudaMemcpyHostToDevice, s);
        if (err != cudaSuccess) {
            g_init_error = static_cast<int>(err);
            return g_init_error;
        }
    }

    // Make the upload visible before the caller launches its first matvec.  On
    // the default stream the following launches are already ordered, so this is
    // a no-op in the common path; it costs one start-up sync and buys "the very
    // first IQ matvec cannot race the upload".
    err = cudaStreamSynchronize(s);
    if (err != cudaSuccess) {
        g_init_error = static_cast<int>(err);
        return g_init_error;
    }

    g_init_bytes = total;
    g_init_error = static_cast<int>(cudaSuccess);
    return g_init_error;
}

/* Bytes the codebooks occupy on the device; 0 when the upload did not happen.
 * Pure host read of file-scope state (no CUDA call), for the backend's
 * QWEN35_PROF line. */
extern "C" unsigned long long q35_iq_tables_bytes(void) {
    return static_cast<unsigned long long>(g_init_bytes);
}

/* 1 once the upload succeeded.  Not used to gate kernels -- those index a null
 * pointer if init failed, which is why the backend turns a failure into a load
 * error -- but it makes "did init actually run?" answerable from a debugger or a
 * test without a device query. */
extern "C" int q35_iq_tables_ready(void) {
    return (g_init_bytes != 0) ? 1 : 0;
}

/* Release the device buffer.  Called from CudaBackend.deinit so a second backend
 * in the same process (tests) does not leak it.  Safe when the upload never
 * happened.  Resets the idempotence flag so a later backend re-uploads. */
extern "C" void q35_launch_deinit_tables(void) {
    if (g_tables != nullptr) {
        (void)cudaFree(g_tables);
        g_tables = nullptr;
    }
    g_init_bytes = 0;
    g_init_attempted = false;
    g_init_error = static_cast<int>(cudaSuccess);
}
